  /* ---------- 80 recorded gunfire: real shots, public domain (CC0), from Freesound ----------
     Each gun's shot is built round a real recording of a gun firing, cut to its first shot and its own echo, levelled and
     kept small (mp3, mono). The synthesised layers in 80-audio still go on top, quieter: the punch for weight, the action's
     clicks, and three slightly different bakes for variety. All are CC0 (no rights reserved); credited here all the same:
       pip       freesound.org/s/163456  Pistol Shot by LeMudCrab
       wasp      freesound.org/s/402789  Small pistol gunshot indoors by acidsnowflake
       quill     freesound.org/s/627087  silenced pistol shot by Clutvh
       hammer    freesound.org/s/683186  357 Magnum Revolver Gunshot by Shark_Anthony
       gnat      freesound.org/s/865993  mp5_fire by db465
       hornet    freesound.org/s/828790  SIG Sauer P226 (Suppressed) by areniporgen
       mako      freesound.org/s/427596  AR15 rifle shot by michorvath
       lancer    freesound.org/s/238916  Rifle Shooting by qubodup
       paladin   freesound.org/s/427598  AR15 pistol shot by michorvath
       vesper    freesound.org/s/828790  SIG Sauer P226 (Suppressed) by areniporgen
       breaker   freesound.org/s/163455  Shotgun Shot by LeMudCrab
       thresher  freesound.org/s/427595  20 gauge shotgun gunshot by michorvath
       stub      freesound.org/s/427595  20 gauge shotgun gunshot by michorvath
       kite      freesound.org/s/421710  SemiAutoRifleShot.wav by SuperPhat
       longbow   freesound.org/s/163460  Sniper Shot by LeMudCrab
       torrent   freesound.org/s/417688  LightMachineGun1.wav by SuperPhat
     (tools: the picks and cuts were made by a script from the Freesound search filtered to CC0, every licence checked on the sound's own page) */
  const GUN_REC = {
    pip: '',
    wasp: '',
    quill: '',
    hammer: '',
    gnat: '',
    hornet: '',
    mako: '',
    lancer: '',
    paladin: '',
    vesper: '',
    breaker: '',
    thresher: '',
    stub: '',
    kite: '',
    longbow: '',
    torrent: '',
  };
  // how each recording sits in its gun: playback rate (a shared recording made deeper or brighter for one of its two guns) and level
  const GUN_REC_FIT = { stub: { r: .9, g: 1 }, thresher: { r: 1.06, g: 1 }, hornet: { r: 1.08, g: .9 }, vesper: { r: .95, g: 1 }, longbow: { r: .92, g: 1.05 }, kite: { r: 1.04, g: 1 }, torrent: { r: .94, g: 1 } };
  const recBufs = {}, recWait = {};
  // the recording for gun k as an audio buffer (decoded once); calls back when it is ready, or with null if it cannot be
  function recBuf(k, cb) { if (recBufs[k] !== undefined) return cb(recBufs[k]); if (!GUN_REC[k] || !K.ac) return cb(null); (recWait[k] = recWait[k] || []).push(cb); if (recWait[k].length > 1) return;
    try { const s = atob(GUN_REC[k]), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
      const done = b => { recBufs[k] = b; const w = recWait[k]; recWait[k] = null; for (const f of w) f(b); };
      const p = K.ac.decodeAudioData(u.buffer, done, () => done(null)); if (p && p.catch) p.catch(() => {}); } catch (e) { recBufs[k] = null; const w = recWait[k]; recWait[k] = null; for (const f of w) f(null); } }
